"""Analyse initial distributions generated by Example 01.

Usage:
    python analyze_results.py --case transverse
    python analyze_results.py --case all
"""

from __future__ import annotations

import argparse
import json
import math
import re
from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from scipy.optimize import brentq

from PASS.utils.table_io import find_table_files, read_table

from generate_input import CASES, selected_cases

SCRIPT_DIR = Path(__file__).resolve().parent


def latest_run_dir(case_name: str, work_dir: Path = SCRIPT_DIR) -> Path:
    """Return the most recent output directory for a generated case."""
    root = work_dir / "output" / case_name
    candidates = [path for path in root.glob("*/*") if path.is_dir() and (path / "distribution").is_dir()]
    if not candidates:
        raise FileNotFoundError(f"No completed run found for '{case_name}'. Run "
                                f"`pass-run --beam0 {CASES[case_name]['input_name']}` first.")
    return max(candidates, key=lambda path: path.stat().st_mtime)


def distribution_files(run_dir: Path) -> list[Path]:
    """Return injection-distribution files in bunch order."""

    def bunch_id(path: Path) -> int:
        match = re.search(r"_bunch(\d+)_", path.name)
        return int(match.group(1)) if match else -1

    return sorted(find_table_files(run_dir / "distribution", "*_injection"), key=bunch_id)


def transverse_emittance(x: np.ndarray, px: np.ndarray) -> float:
    """Return RMS geometric emittance from a transverse covariance matrix."""
    x_centered = x - np.mean(x)
    px_centered = px - np.mean(px)
    determinant = (np.mean(x_centered**2) * np.mean(px_centered**2) - np.mean(x_centered * px_centered)**2)
    return math.sqrt(max(float(determinant), 0.0))


def transverse_twiss(x: np.ndarray, px: np.ndarray) -> tuple[float, float, float]:
    """Return (emittance, alpha, beta) from centered particle coordinates."""
    x_centered = x - np.mean(x)
    px_centered = px - np.mean(px)
    sigma_x2 = float(np.mean(x_centered**2))
    sigma_px2 = float(np.mean(px_centered**2))
    sigma_xpx = float(np.mean(x_centered * px_centered))
    emit = math.sqrt(max(sigma_x2 * sigma_px2 - sigma_xpx**2, 0.0))
    if emit <= 0.0:
        return emit, 0.0, 0.0
    return emit, -sigma_xpx / emit, sigma_x2 / emit


def relative_error(actual: float, theory: float | None) -> float | None:
    """Return (actual - theory) / theory, or None when no theory is defined."""
    if theory is None or abs(theory) < 1e-30:
        return None
    return (actual - theory) / theory


def normalized_actions(df) -> tuple[np.ndarray, np.ndarray]:
    """Return I_x/(4 epsilon_x), I_y/(4 epsilon_y) using configured Twiss values.

    The example has zero dispersion and zero centroid offsets. The stable
    normalized-coordinate formula avoids cancellation at nonzero alpha.
    """
    actions = []
    for axis, beta_key in (("x", "Beta x"), ("y", "Beta Y")):
        alpha = float(df.headers[f"Alpha {axis}"])
        beta = float(df.headers[beta_key])
        emit = float(df.headers[f"Emit {axis}"])
        if emit <= 0.0:
            raise ValueError("Action diagnostics require positive RMS geometric emittance in both planes")
        position = df[axis].to_numpy(dtype=float)
        momentum = df[f"p{axis}"].to_numpy(dtype=float)
        u = position / math.sqrt(beta * emit)
        v = (alpha * position + beta * momentum) / math.sqrt(beta * emit)
        actions.append((u * u + v * v) / 4.0)
    return actions[0], actions[1]


def _action_roundoff_tolerance(df) -> float:
    """Propagate stored-coordinate rounding through the Twiss action map."""
    errors = np.zeros(len(df), dtype=float)
    arithmetic_epsilon = np.finfo(float).eps
    for axis, beta_key in (("x", "Beta x"), ("y", "Beta Y")):
        alpha = float(df.headers[f"Alpha {axis}"])
        beta = float(df.headers[beta_key])
        emit = float(df.headers[f"Emit {axis}"])
        position_raw = df[axis].to_numpy()
        momentum_raw = df[f"p{axis}"].to_numpy()
        position_epsilon = np.finfo(position_raw.dtype).eps if position_raw.dtype.kind == "f" else 0.0
        momentum_epsilon = np.finfo(momentum_raw.dtype).eps if momentum_raw.dtype.kind == "f" else 0.0
        position = position_raw.astype(float)
        momentum = momentum_raw.astype(float)
        scale = math.sqrt(beta * emit)
        u = position / scale
        v = (alpha * position + beta * momentum) / scale
        # Absolute termwise errors account for cancellation in alpha*x + beta*px.
        u_error = (position_epsilon + 2.0 * arithmetic_epsilon) * np.abs(u)
        v_error = ((position_epsilon + 4.0 * arithmetic_epsilon) * np.abs(alpha * position) +
                   (momentum_epsilon + 4.0 * arithmetic_epsilon) * np.abs(beta * momentum)) / scale
        errors += (0.5 * (np.abs(u) * u_error + np.abs(v) * v_error) + 0.25 * (u_error**2 + v_error**2) + arithmetic_epsilon * (u**2 + v**2))
    # A factor of two covers coefficient rounding; keep the strict float64 floor.
    return max(1e-10, 2.0 * float(np.max(errors)))


def uniform_cdf_error(values: np.ndarray) -> float:
    """Return the two-sided empirical CDF distance from Uniform[0, 1]."""
    ordered = np.sort(values)
    cdf = np.clip(ordered, 0.0, 1.0)
    n = len(ordered)
    return float(max(np.max(np.arange(1, n + 1) / n - cdf), np.max(cdf - np.arange(n) / n)))


def transverse_checks(df, summary: dict) -> list[dict]:
    """Check second moments, action correlations, and the defining support."""
    action_x, action_y = normalized_actions(df)
    n = len(df)
    distribution = summary["transverse"]
    checks = []
    moment_tolerance = max(0.02, 8.0 / math.sqrt(n))
    correlation_tolerance = max(0.025, 8.0 / math.sqrt(n))

    def check(name: str, measured: float, theory: float, tolerance: float, *, upper_bound: bool = False):
        error = measured - theory
        checks.append({
            "transverse": distribution,
            "check": name,
            "measured": measured,
            "theory": theory,
            "error": error,
            "tolerance": tolerance,
            "comparison": "upper_bound" if upper_bound else "absolute_error",
            "passed": bool(error <= tolerance if upper_bound else abs(error) <= tolerance),
        })

    for axis in ("x", "y"):
        check(f"rms_geometric_emittance_{axis}_ratio", summary[f"emit_{axis}"] / summary[f"theory_emit_{axis}"], 1.0, moment_tolerance)
        check(f"twiss_beta_{axis}_ratio", summary[f"beta_{axis}"] / summary[f"theory_beta_{axis}"], 1.0, moment_tolerance)
        check(f"twiss_alpha_{axis}", summary[f"alpha_{axis}"], summary[f"theory_alpha_{axis}"],
              moment_tolerance * max(1.0, abs(summary[f"theory_alpha_{axis}"])))
    check("action_x_mean", float(np.mean(action_x)), 0.5, moment_tolerance / 2.0)
    check("action_y_mean", float(np.mean(action_y)), 0.5, moment_tolerance / 2.0)
    theory_correlation = {"gaussian": 0.0, "uniform-real": 0.0, "uniform-phase": 0.0, "kv": -1.0, "waterbag": -0.5, "parabolic": -1.0 / 3.0}
    correlation = float(np.corrcoef(action_x, action_y)[0, 1])
    check("action_correlation", correlation, theory_correlation[distribution], correlation_tolerance)
    summary.update(action_x_mean=float(np.mean(action_x)),
                   action_y_mean=float(np.mean(action_y)),
                   action_correlation=correlation,
                   theory_action_correlation=theory_correlation[distribution],
                   action_x_max=float(np.max(action_x)),
                   action_y_max=float(np.max(action_y)),
                   action_sum_max=float(np.max(action_x + action_y)))
    support_tolerance = _action_roundoff_tolerance(df)
    summary["action_support_tolerance"] = support_tolerance
    if distribution == "uniform-phase":
        for axis, values in (("x", action_x), ("y", action_y)):
            check(f"action_{axis}_max", float(np.max(values)), 1.0, support_tolerance, upper_bound=True)
            distance = uniform_cdf_error(values)
            summary[f"action_{axis}_uniform_cdf_error"] = distance
            check(f"action_{axis}_uniform_cdf_error", distance, 0.0, max(0.012, 4.0 / math.sqrt(n)))
        joint = np.histogram2d(action_x, action_y, bins=10, range=((0.0, 1.0), (0.0, 1.0)))[0] / n
        check("joint_action_cell_max_error", float(np.max(np.abs(joint - 0.01))), 0.0, max(0.0015, 0.8 / math.sqrt(n)))
    elif distribution == "kv":
        check("action_sum_max_error", float(np.max(np.abs(action_x + action_y - 1.0))), 0.0, support_tolerance)
    elif distribution in {"waterbag", "parabolic"}:
        bound = 1.5 if distribution == "waterbag" else 2.0
        check("action_sum_max", float(np.max(action_x + action_y)), bound, support_tolerance, upper_bound=True)
    elif distribution == "uniform-real":
        for axis, values in (("x", action_x), ("y", action_y)):
            check(f"action_{axis}_max", float(np.max(values)), 1.5, support_tolerance, upper_bound=True)
    return checks


def rf_bucket_theory(headers) -> dict:
    """Calculate the RF bucket limits using PASS InjectionBunchInfo formulas."""
    kinetic_energy = float(headers["Ek"])
    mass = float(headers["m0"])
    circumference = 2.0 * math.pi * float(headers["Rho"])
    gamma_t = float(headers["Gamma T"])
    harmonic = int(headers["Harmonic num"])
    voltage = float(headers["RF voltage"])
    phase = float(headers["RF phase"])
    charge = float(headers["Charge num"])
    mass_number = int(headers["Proton num"]) + int(headers["Neutron num"])
    qm_ratio = abs(charge) / mass_number

    gamma = 1.0 + kinetic_energy / mass
    beta = math.sqrt(1.0 - 1.0 / gamma**2)
    total_energy = kinetic_energy + mass
    eta = 1.0 / gamma_t**2 - 1.0 / gamma**2
    rho = circumference / (2.0 * math.pi)
    pi = math.pi

    if harmonic <= 0 or abs(voltage) < 1e-30 or abs(eta) < 1e-30:
        return {}

    def separatrix_equation(phi: float) -> float:
        return (math.cos(phi) + phi * math.sin(phase) + math.cos(phase) - (pi - phase) * math.sin(phase))

    if eta < 0.0:
        phi_min = brentq(separatrix_equation, -pi, phase)
        phi_max = pi - phase
    else:
        phi_min = pi - phase
        phi_max = brentq(separatrix_equation, phase, 2.0 * pi)

    def z_from_phi(phi: float) -> float:
        return rho * (phase - phi) / harmonic

    z_min = z_from_phi(phi_max)
    z_max = z_from_phi(phi_min)
    dp_temp = (-qm_ratio * voltage / (pi * beta**2 * total_energy * harmonic * eta) * (2.0 * math.cos(phase) - (pi - 2.0 * phase) * math.sin(phase)))
    dp_max = math.sqrt(max(dp_temp, 0.0))
    qs_temp = (-qm_ratio * harmonic * voltage * eta * math.cos(phase) / (2.0 * pi * beta**2 * total_energy))
    qs = math.sqrt(max(qs_temp, 0.0))

    return {
        "bucket_z_min": z_min,
        "bucket_z_max": z_max,
        "bucket_dp_max": dp_max,
        "synchrotron_tune": qs,
        "slip_factor": eta,
    }


def summarise(path: Path) -> dict:
    """Read one distribution file and return validation and RMS statistics."""
    df = read_table(path)
    values = df[["x", "px", "y", "py", "z", "dp"]].to_numpy(dtype=float)
    if not np.isfinite(values).all():
        raise ValueError(f"Non-finite particle coordinates in {path}")

    headers = df.headers
    emit_x, alpha_x, beta_x = transverse_twiss(df["x"].to_numpy(), df["px"].to_numpy())
    emit_y, alpha_y, beta_y = transverse_twiss(df["y"].to_numpy(), df["py"].to_numpy())

    alpha_x_theory = float(headers["Alpha x"])
    alpha_y_theory = float(headers["Alpha y"])
    beta_x_theory = float(headers["Beta x"])
    beta_y_theory = float(headers["Beta Y"])
    emit_x_theory = float(headers["Emit x"])
    emit_y_theory = float(headers["Emit y"])
    gamma_x_theory = (1.0 + alpha_x_theory**2) / beta_x_theory
    gamma_y_theory = (1.0 + alpha_y_theory**2) / beta_y_theory
    sigma_x_theory = math.sqrt(beta_x_theory * emit_x_theory)
    sigma_px_theory = math.sqrt(gamma_x_theory * emit_x_theory)
    sigma_y_theory = math.sqrt(beta_y_theory * emit_y_theory)
    sigma_py_theory = math.sqrt(gamma_y_theory * emit_y_theory)

    longitudinal = str(headers["Longi type"]).lower()
    configured_sigma_z = float(headers["Sigma z"])
    configured_sigma_dp = float(headers["Delta p/p"])
    theory_sigma_z = None
    theory_sigma_dp = None
    bucket = {}
    if longitudinal == "gaussian":
        theory_sigma_z = configured_sigma_z
        theory_sigma_dp = configured_sigma_dp
    elif longitudinal == "coasting":
        circumference = 2.0 * math.pi * float(headers["Rho"])
        theory_sigma_z = circumference / math.sqrt(12.0)
        theory_sigma_dp = configured_sigma_dp
    elif longitudinal in {"matchz", "matchdp"}:
        bucket = rf_bucket_theory(headers)
        if longitudinal == "matchdp":
            theory_sigma_dp = configured_sigma_dp

    summary = {
        "file": path.name,
        "transverse": str(headers["Trans type"]),
        "longitudinal": str(headers["Longi type"]),
        "particles": len(df),
        "sigma_x": float(df["x"].std(ddof=0)),
        "sigma_px": float(df["px"].std(ddof=0)),
        "sigma_y": float(df["y"].std(ddof=0)),
        "sigma_py": float(df["py"].std(ddof=0)),
        "sigma_z": float(df["z"].std(ddof=0)),
        "sigma_dp": float(df["dp"].std(ddof=0)),
        "emit_x": emit_x,
        "emit_y": emit_y,
        "alpha_x": alpha_x,
        "alpha_y": alpha_y,
        "beta_x": beta_x,
        "beta_y": beta_y,
        "theory_sigma_x": sigma_x_theory,
        "theory_sigma_px": sigma_px_theory,
        "theory_sigma_y": sigma_y_theory,
        "theory_sigma_py": sigma_py_theory,
        "theory_emit_x": emit_x_theory,
        "theory_emit_y": emit_y_theory,
        "theory_alpha_x": alpha_x_theory,
        "theory_alpha_y": alpha_y_theory,
        "theory_beta_x": beta_x_theory,
        "theory_beta_y": beta_y_theory,
        "theory_sigma_z": theory_sigma_z,
        "theory_sigma_dp": theory_sigma_dp,
        "requested_sigma_z": configured_sigma_z if longitudinal == "matchz" else None,
        "requested_sigma_dp": configured_sigma_dp if longitudinal == "matchdp" else None,
        "sigma_x_rel_error": relative_error(float(df["x"].std(ddof=0)), sigma_x_theory),
        "sigma_px_rel_error": relative_error(float(df["px"].std(ddof=0)), sigma_px_theory),
        "sigma_y_rel_error": relative_error(float(df["y"].std(ddof=0)), sigma_y_theory),
        "sigma_py_rel_error": relative_error(float(df["py"].std(ddof=0)), sigma_py_theory),
        "emit_x_rel_error": relative_error(emit_x, emit_x_theory),
        "emit_y_rel_error": relative_error(emit_y, emit_y_theory),
        "alpha_x_abs_error": alpha_x - alpha_x_theory,
        "alpha_y_abs_error": alpha_y - alpha_y_theory,
        "beta_x_rel_error": relative_error(beta_x, beta_x_theory),
        "beta_y_rel_error": relative_error(beta_y, beta_y_theory),
        "sigma_z_rel_error": relative_error(float(df["z"].std(ddof=0)), theory_sigma_z),
        "sigma_dp_rel_error": relative_error(float(df["dp"].std(ddof=0)), theory_sigma_dp),
        "bucket_z_min": bucket.get("bucket_z_min"),
        "bucket_z_max": bucket.get("bucket_z_max"),
        "bucket_dp_max": bucket.get("bucket_dp_max"),
        "synchrotron_tune": bucket.get("synchrotron_tune"),
        "slip_factor": bucket.get("slip_factor"),
        "configured_sigma_z": configured_sigma_z,
        "configured_sigma_dp": configured_sigma_dp,
        "z_min": float(df["z"].min()),
        "z_max": float(df["z"].max()),
        "dp_min": float(df["dp"].min()),
        "dp_max": float(df["dp"].max()),
    }
    if longitudinal == "matchz" and bucket:
        nearest_bucket_boundary = min(
            abs(bucket["bucket_z_min"]),
            abs(bucket["bucket_z_max"]),
        )
        summary["matchz_bucket_limit_ratio"] = (configured_sigma_z / nearest_bucket_boundary)
        summary["matchz_requested_4sigma_ratio"] = (4.0 * configured_sigma_z / nearest_bucket_boundary)
    else:
        summary["matchz_bucket_limit_ratio"] = None
        summary["matchz_requested_4sigma_ratio"] = None
    return summary


def plot_distributions(case_name: str, files: list[Path], analysis_dir: Path) -> Path:
    """Save x-px, y-py, and z-dp scatter plots for every bunch in a case."""
    fig, axes = plt.subplots(
        len(files),
        3,
        figsize=(13, 3.4 * len(files)),
        squeeze=False,
    )

    for bunch_id, path in enumerate(files):
        df = read_table(path)
        headers = df.headers
        label = f"bunch{bunch_id}: {headers['Trans type']} / {headers['Longi type']}"
        planes = [
            ("x", "px", "x (m)", "px", "x-px"),
            ("y", "py", "y (m)", "py", "y-py"),
            ("z", "dp", "z (m)", "dp", "z-dp"),
        ]
        for axis, (x_name, y_name, x_label, y_label, title) in zip(axes[bunch_id], planes):
            axis.scatter(
                df[x_name],
                df[y_name],
                s=1.0,
                alpha=0.28,
                linewidths=0,
                rasterized=True,
            )
            axis.set_xlabel(x_label)
            axis.set_ylabel(y_label)
            axis.set_title(f"{label}, {title}")
            axis.grid(alpha=0.25)

    fig.tight_layout()
    plot_path = analysis_dir / f"{case_name}_distributions.png"
    fig.savefig(plot_path, dpi=160)
    plt.close(fig)
    return plot_path


def plot_action_diagnostics(case_name: str, files: list[Path], analysis_dir: Path) -> Path:
    """Save joint normalized actions, which distinguish KV from independent disks."""
    columns = min(3, len(files))
    rows = math.ceil(len(files) / columns)
    fig, axes = plt.subplots(rows, columns, figsize=(4.8 * columns, 4.2 * rows), squeeze=False)
    for axis, path in zip(axes.flat, files):
        df = read_table(path)
        action_x, action_y = normalized_actions(df)
        distribution = str(df.headers["Trans type"])
        limit = max(1.05, float(np.max(action_x)), float(np.max(action_y)))
        axis.hist2d(action_x, action_y, bins=80, range=((0.0, limit), (0.0, limit)), cmap="Blues", cmin=1)
        if distribution == "uniform-phase":
            axis.plot([0, 1, 1, 0, 0], [0, 0, 1, 1, 0], color="darkorange", linewidth=1.2)
        elif distribution in {"kv", "waterbag", "parabolic"}:
            bound = {"kv": 1.0, "waterbag": 1.5, "parabolic": 2.0}[distribution]
            axis.plot([0, bound], [bound, 0], color="darkorange", linewidth=1.2)
        axis.set(xlabel=r"$I_x/(4\varepsilon_x)$",
                 ylabel=r"$I_y/(4\varepsilon_y)$",
                 title=f"{distribution}: correlation = {np.corrcoef(action_x, action_y)[0, 1]:+.4f}",
                 xlim=(0, limit),
                 ylim=(0, limit))
        axis.set_aspect("equal")
    for axis in list(axes.flat)[len(files):]:
        axis.set_visible(False)
    fig.tight_layout()
    plot_path = analysis_dir / f"{case_name}_joint_actions.png"
    fig.savefig(plot_path, dpi=180)
    fig.savefig(plot_path.with_suffix(".pdf"))
    plt.close(fig)
    return plot_path


def analyse_case(case_name: str, work_dir: Path = SCRIPT_DIR) -> None:
    """Validate files and write a compact summary plus distribution plots."""
    run_dir = latest_run_dir(case_name, work_dir)
    files = distribution_files(run_dir)
    expected_specs = CASES[case_name]["bunches"]

    if len(files) != len(expected_specs):
        raise ValueError(f"{case_name}: expected {len(expected_specs)} saved bunches, found {len(files)}")

    summaries = []
    checks = []
    for bunch_id, (path, expected) in enumerate(zip(files, expected_specs)):
        summary = summarise(path)
        if summary["transverse"] != expected["transverse"]:
            raise ValueError(f"{path.name}: expected transverse={expected['transverse']}, "
                             f"got {summary['transverse']}")
        if summary["longitudinal"] != expected["longitudinal"]:
            raise ValueError(f"{path.name}: expected longitudinal={expected['longitudinal']}, "
                             f"got {summary['longitudinal']}")
        summary["bunch"] = bunch_id
        bunch_checks = transverse_checks(read_table(path), summary)
        for check in bunch_checks:
            check["bunch"] = bunch_id
        checks.extend(bunch_checks)
        summaries.append(summary)

    analysis_dir = run_dir / "analysis"
    analysis_dir.mkdir(exist_ok=True)
    summary_path = analysis_dir / f"{case_name}_summary.csv"
    pd.DataFrame(summaries).to_csv(summary_path, index=False)
    plot_path = plot_distributions(case_name, files, analysis_dir)
    action_plot_path = plot_action_diagnostics(case_name, files, analysis_dir)
    checks_path = analysis_dir / f"{case_name}_physics_checks.csv"
    pd.DataFrame(checks).to_csv(checks_path, index=False)
    report_path = analysis_dir / f"{case_name}_physics_checks.json"
    report_path.write_text(json.dumps({"passed": all(check["passed"] for check in checks), "checks": checks}, indent=2), encoding="utf-8")

    print(f"[Analyse] {case_name}")
    print(f"  run: {run_dir}")
    print(f"  summary: {summary_path}")
    print(f"  plot: {plot_path}")
    print(f"  joint actions: {action_plot_path}")
    print(f"  physics checks: {checks_path} ({sum(check['passed'] for check in checks)}/{len(checks)} passed)")
    for summary in summaries:
        print(f"  bunch{summary['bunch']}: {summary['transverse']}/"
              f"{summary['longitudinal']}, N={summary['particles']}, "
              f"emit_x={summary['emit_x']:.4e} "
              f"(theory {summary['theory_emit_x']:.4e}, "
              f"err {summary['emit_x_rel_error']:+.2%}), "
              f"emit_y={summary['emit_y']:.4e} "
              f"(theory {summary['theory_emit_y']:.4e}, "
              f"err {summary['emit_y_rel_error']:+.2%})")
        if summary["theory_sigma_z"] is not None:
            print(f"    sigma_z={summary['sigma_z']:.4e} "
                  f"(theory {summary['theory_sigma_z']:.4e}, "
                  f"err {summary['sigma_z_rel_error']:+.2%})")
        elif summary["longitudinal"].lower() == "matchz":
            print(f"    sigma_z={summary['sigma_z']:.4e} "
                  f"(requested {summary['requested_sigma_z']:.4e}; "
                  f"requested 4-sigma / nearest bucket boundary="
                  f"{summary['matchz_requested_4sigma_ratio']:.3f})")
        if summary["theory_sigma_dp"] is not None:
            print(f"    sigma_dp={summary['sigma_dp']:.4e} "
                  f"(theory {summary['theory_sigma_dp']:.4e}, "
                  f"err {summary['sigma_dp_rel_error']:+.2%})")
        if summary["bucket_dp_max"] is not None:
            print(f"    RF theory: z=[{summary['bucket_z_min']:.4e}, "
                  f"{summary['bucket_z_max']:.4e}] m, "
                  f"dp_max={summary['bucket_dp_max']:.4e}, "
                  f"Qs={summary['synchrotron_tune']:.4e}")
            if summary["longitudinal"].lower() == "matchz":
                print(f"    MatchZ requested sigma_z={summary['requested_sigma_z']:.4e}; "
                      f"bucket z span is not large enough for 4 sigma")
    failures = [check for check in checks if not check["passed"]]
    if failures:
        details = "; ".join(f"{check['transverse']} {check['check']}: measured={check['measured']:.8g}, theory={check['theory']:.8g}, "
                            f"error={check['error']:.8g}, tolerance={check['tolerance']:.8g}" for check in failures)
        raise ValueError(f"Transverse physics validation failed: {details}")


def main() -> None:
    parser = argparse.ArgumentParser(description="Analyse Example 01 outputs.")
    parser.add_argument(
        "--case",
        choices=["all", *CASES],
        default="all",
        help="Completed case to analyse (default: all).",
    )
    parser.add_argument("--work-dir", type=Path, default=SCRIPT_DIR, help="Directory containing output/<case>/ (default: this example directory).")
    args = parser.parse_args()

    for case_name in selected_cases(args.case):
        analyse_case(case_name, args.work_dir)


if __name__ == "__main__":
    main()
